{"settings":"{
  // Enable / Disable the spell checker.
  "cSpell.enabled": true,

  // Specifies the style of the gravatar default (fallback) images
  //  - identicon: A geometric pattern
  //  - mp: A simple, cartoon-style silhouetted outline of a person (does not vary by email hash)
  //  - monsterid: A monster with different colors, faces, etc
  //  - retro: 8-bit arcade-style pixelated faces
  //  - robohash: A robot with different colors, faces, etc
  //  - wavatar: A face with differing features and backgrounds
  "gitlens.defaultGravatarsStyle": "robohash",

  // Deprecated. Use the pre-release of GitLens instead
  //
  "gitlens.insiders": null,

  // Specifies how much (if any) output will be sent to the GitLens output channel
  //  - off: Logs nothing
  //  - error: Logs only errors
  //  - warn: Logs errors and warnings
  //  - info: Logs errors, warnings, and messages
  //  - debug: Logs verbose errors, warnings, and messages. Best for issue reporting.
  "gitlens.outputLevel": "warn",

  // Specifies whether to hide or show features that require a trial or GitLens Pro and are not accessible given the opened repositories and current trial or plan
  "gitlens.plusFeatures.enabled": true,

  // Specifies the proxy configuration to use. If not specified, the proxy configuration will be determined based on VS Code or OS settings
  "gitlens.proxy": null,

  // Specifies whether to show the What's New notification after upgrading to new feature releases
  "gitlens.showWhatsNewAfterUpgrades": true,

  // Specifies whether to enable virtual repositories support
  "gitlens.virtualRepositories.enabled": true,
  "powermode.enabled": true,

  // Choose between different preset gifs to use when powermode is activated
  "powermode.presets": "flames",

  // (**PRO feature**) Allow `console.log` to trigger predictions
  //
  //  _(Always disabled for Community edition)_
  "console-ninja.allowConsoleLogToTriggerPredictions": false,

  // The list of host names that may connect to Console Ninja. Defaults to the current machine IP addresses and host name (`localhost`, `127.0.0.1`, `example.cypress.io`, `os.hostname()`, Network Adapter IP v4 Addresses).
  //
  // (**PRO feature**) also supports the use of `*` and `?` for wildcard matching (e.g. `*.example.com`), and regular expressions (e.g. `/^.*\\.example\\.com$/`).
  //
  // Add additional host names if you need to connect to Console Ninja from a different/custom host name **(restart editor after changing this setting)**.
  "console-ninja.allowedHosts": [],

  // Choose whether to use Pro or Community feature set.
  //  - Pro: Use all Console Ninja features
  //  - Community: Only use Console Ninja features that will be available in the free Community Edition
  "console-ninja.featureSet": "Community",

  // Install [bin](https://github.com/wallabyjs/console-ninja#universal-node-applications) folder to PATH.
  "console-ninja.installBinToPath": true,

  // (**PRO feature**) Enable Predictive Logging
  //
  //  _(Always disabled for Community edition)_
  "console-ninja.predictiveLoggingEnabled": true,

  // (**PRO feature**) Template of web search URL. Use `{query}` placeholder to specify where to put the search query.
  "console-ninja.searchUrl": "https://www.google.com/search?q={query}",

  // Display information about new features when they are released.
  "console-ninja.showWhatsNew": true,

  // Synchronize subscription details and other settings as a part of VS Code Settings Sync
  "console-ninja.syncSettings": true,

  // Tools (node modules and extensions) to automatically enable Console Ninja for.
  "console-ninja.toolsToEnableSupportAutomaticallyFor": {
    "vite": true,
    "angular": true,
    "jest": true,
    "webpack": true,
    "next.js": true,
    "nest.js": true,
    "cypress": true,
    "http-server": true,
    "serve": true,
    "live-server": true,
    "nuxt": true,
    "remix": true,
    "qwik": true,
    "hydrogen": true,
    "serverless": true,
    "astro": true,
    "live-server-extension": false,
    "live-preview-extension": false
  },

  // Warn when no supported tools are detected.
  "console-ninja.warnOnNoToolsDetected": true,

  // Control whether the combo counter is visible.
  //  - show: Show the combo counter
  //  - hide: Hide the combo counter
  //  - default: Use the default value. May be overridden by other settings.
  "powermode.combo.counterEnabled": "default",

  // Control the size of the Combo Meter text
  "powermode.combo.counterSize": 3,

  // Control where all the combo information is visible.
  //  - editor: Show the combo in the editor. The true 'Power Mode' experience
  //  - statusbar: Use the status bar. A more subdued experience.
  //  - default: Use the default value. May be overiddent by other settings.
  //  - off: Turn off the combo entirely.
  "powermode.combo.location": "default",

  // The combo number needed to activate POWER MODE!!! and start shaking and exploding the screen! If the value is 0, POWER MODE will always be active.
  "powermode.combo.threshold": 0,

  // The number of seconds before the combo resets. If the value is 0, the timer will never reset.
  "powermode.combo.timeout": 10,

  // Control whether the combo timer is visible.
  //  - show: Show the combo timer
  //  - hide: Hide the combo timer
  //  - default: Use the default value. May be overridden by other settings.
  "powermode.combo.timerEnabled": "default",

  // Determines if words must match case and accent rules.
  //
  // - `false` - Case is ignored and accents can be missing on the entire word.
  //   Incorrect accents or partially missing accents will be marked as incorrect.
  //   Note: Some languages like Portuguese have case sensitivity turned on by default.
  //   You must use `cSpell.languageSettings` to turn it off.
  // - `true` - Case and accents are enforced by default.
  "cSpell.caseSensitive": false,

  // Define custom dictionaries to be included by default.
  // If `addWords` is `true` words will be added to this dictionary.
  //
  //
  // **Example:**
  //
  // ```js
  // "cSpell.customDictionaries": {
  //   "project-words": {
  //     "name": "project-words",
  //     "path": "${workspaceRoot}/project-words.txt",
  //     "description": "Words used in this project",
  //     "addWords": true
  //   },
  //   "custom": true, // Enable the `custom` dictionary
  //   "internal-terms": false // Disable the `internal-terms` dictionary
  // }
  // ```
  "cSpell.customDictionaries": {},

  // Optional list of dictionaries to use.
  // Each entry should match the name of the dictionary.
  // To remove a dictionary from the list add `!` before the name.
  // i.e. `!typescript` will turn off the dictionary with the name `typescript`.
  "cSpell.dictionaries": [],

  // Define additional available dictionaries.
  "cSpell.dictionaryDefinitions": [],

  // List of words to always be considered incorrect. Words found in `flagWords` override `words`.
  //
  // Format of `flagWords`
  // - single word entry - `word`
  // - with suggestions - `word:suggestion` or `word->suggestion, suggestions`
  //
  // Example:
  // ```ts
  // "flagWords": [
  //   "color: colour",
  //   "incase: in case, encase",
  //   "canot->cannot",
  //   "cancelled->canceled"
  // ]
  // ```
  "cSpell.flagWords": [],

  // A list of words to be ignored by the spell checker.
  "cSpell.ignoreWords": [],

  // Current active spelling language.
  //
  // Example: "en-GB" for British English
  //
  // Example: "en,nl" to enable both English and Dutch
  "cSpell.language": "en",

  // Additional settings for individual programming languages and locales.
  "cSpell.languageSettings": [],

  // Optional list of dictionaries that will not be used for suggestions.
  // Words in these dictionaries are considered correct, but will not be
  // used when making spell correction suggestions.
  //
  // Note: if a word is suggested by another dictionary, but found in
  // one of these dictionaries, it will be removed from the set of
  // possible suggestions.
  "cSpell.noSuggestDictionaries": [],

  // Words to add to global dictionary -- should only be in the user config file.
  "cSpell.userWords": [],

  // List of words to be considered correct.
  "cSpell.words": [],

  // Clear [log viewer](https://github.com/wallabyjs/console-ninja#log-viewer) entries when any file changes (default value after editor restart).
  "console-ninja.autoClearLogViewerOnFileChanges": true,

  // Default display mode for [log viewer](https://github.com/wallabyjs/console-ninja#log-viewer) entry date and time.
  //  - Relative To Oldest: (**PRO feature**) Displays time relative to the oldest entry in the log viewer
  //  - Relative To Previous: (**PRO feature**) Displays time relative to the previous entry in the log viewer
  //  - Absolute: Displays absolute date and time
  //  - None: Does not display date and time
  "console-ninja.dateTimeDisplayMode": "Absolute",

  // [Format string](https://day.js.org/docs/en/display/format) for displaying [log viewer](https://github.com/wallabyjs/console-ninja#log-viewer) entry date and time (**empty string** to disable date and time display).
  "console-ninja.dateTimeFormat": "HH:mm:ss.SSS",

  // Controls the font size (in pixels) of the [Console Ninja Output](https://github.com/wallabyjs/console-ninja#log-viewer). Restart Console Output after changing this setting.
  "console-ninja.fontSize": 10,

  // Maximum number of entries to display in the [log viewer](https://github.com/wallabyjs/console-ninja#log-viewer).
  "console-ninja.maxLogViewerEntries": 15000,

  // Open `http`/`https` source links in editor as new file.
  "console-ninja.openHttpLinksInEditor": true,

  // Specifies how [Console Ninja Output](https://github.com/wallabyjs/console-ninja#log-viewer) is displayed.
  //  - Beside File: Opens Console Ninja Output beside your current file
  //  - In View: Opens Console Ninja Output in a separate view
  "console-ninja.outputMode": "Beside File",

  // Display notification that Console Ninja is running into build tools CLI and browser developer tools console.
  "console-ninja.showWelcomeMessageInTools": true,

  // If this setting is false, no telemetry will be sent regardless of the new setting's value. Deprecated due to being combined into the `telemetry.telemetryLevel` setting.
  // Enable crash reports to be collected. This helps us improve stability.
  // This option requires restart to take effect.
  "telemetry.enableCrashReporter": true,

  // If this setting is false, no telemetry will be sent regardless of the new setting's value. Deprecated in favor of the `telemetry.telemetryLevel` setting.
  // Enable diagnostic data to be collected. This helps us to better understand how Visual Studio Code is performing and where improvements need to be made. [Read more](https://go.microsoft.com/fwlink/?LinkId=521839) about what we collect and our privacy statement.
  "telemetry.enableTelemetry": true,

  //
  // Controls Visual Studio Code telemetry, first-party extension telemetry, and participating third-party extension telemetry. Some third party extensions might not respect this setting. Consult the specific extension's documentation to be sure. Telemetry helps us better understand how Visual Studio Code is performing, where improvements need to be made, and how features are being used. Read more about the [data we collect](https://aka.ms/vscode-telemetry) and our [privacy statement](https://go.microsoft.com/fwlink/?LinkId=521839). A full restart of the application is necessary for crash reporting changes to take effect.
  //
  // &nbsp;
  //
  // The following table outlines the data sent with each setting:
  //
  // |       | Crash Reports | Error Telemetry | Usage Data |
  // |:------|:---------------------:|:---------------:|:--------------:|
  // | all   |            ✓          |        ✓        |        ✓       |
  // | error |            ✓          |        ✓        |        -       |
  // | crash |            ✓          |        -        |        -       |
  // | off   |            -          |        -        |        -       |
  //
  //
  // &nbsp;
  //
  // ****Note:*** If this setting is 'off', no telemetry will be sent regardless of other telemetry settings. If this setting is set to anything except 'off' and telemetry is disabled with deprecated settings, no telemetry will be sent.*
  //
  //  - all: Sends usage data, errors, and crash reports.
  //  - error: Sends general error telemetry and crash reports.
  //  - crash: Sends OS level crash reports.
  //  - off: Disables all product telemetry.
  "telemetry.telemetryLevel": "all",

  // (**PRO feature**) Specifies whether Console Ninja can provide **LLM chat** requested source code files without prompts.
  //  - Always Prompt: Always prompt for LLM requested files
  //  - Always Reply Automatically: Provide LLM requested files without prompts
  "console-ninja.AI.codeLoaderConsentMode": "Always Prompt",

  // (**PRO feature**) Specifies whether Console Ninja can provide **LLM agent** requested runtime logs and errors without prompts.
  //  - Always Prompt: Always prompt for LLM requested logs and errors
  //  - Always Reply Automatically: Provide LLM requested logs and errors without prompts
  "console-ninja.AI.logsAndErrorsConsentMode": "Always Prompt",

  // (**PRO feature**) Specifies whether Console Ninja can provide **LLM chat** requested file logs without prompts.
  //  - Always Prompt: Always prompt for LLM requested file logs
  //  - Always Reply Automatically: Provide LLM requested file logs without prompts
  "console-ninja.AI.logsLoaderConsentMode": "Always Prompt",

  // Include function names found inside logged objects.
  "console-ninja.captureFunctions": false,

  // (**PRO feature**) Capture and display errors.
  //
  //  _(Always enabled for Community edition)_
  "console-ninja.output.showErrors": true,

  // (**PRO feature**) Capture and display logs only from [logpoints](https://github.com/wallabyjs/console-ninja#logpoints), [function logpoints](https://github.com/wallabyjs/console-ninja#function-logpoints), [tracepoints](https://github.com/wallabyjs/console-ninja#tracepoints) and [timepoints](https://github.com/wallabyjs/console-ninja#timepoints), and do not capture `console.log`, `console.trace`, `console.time`, `console.warn`, `console.info`, or `console.debug`.
  //
  //  _(Always disabled for Community edition)_
  "console-ninja.output.showLogsFromLogPointsOnly": false,

  // (**PRO feature**) Display logs from multiple running tools together in a single list in [log viewer](https://github.com/wallabyjs/console-ninja#log-viewer).
  //
  //  _(Always disabled for Community edition)_
  "console-ninja.output.showLogsFromMultipleRunningToolsTogether": false,

  // (**PRO feature**) Capture and display logs only from files opened in editor.
  //
  //  _(Always disabled for Community edition)_
  "console-ninja.output.showLogsOnlyFromOpenedFiles": false,

  // (**PRO feature**) Capture and display network requests.
  //
  //  _(Always enabled with reduced functionality for Community edition)_
  "console-ninja.output.showNetworkRequests": true,

  // If a `cspell` configuration file is updated, format the configuration file
  // using the VS Code Format Document Provider. This will cause the configuration
  // file to be saved prior to being updated.
  "cSpell.autoFormatConfigFile": false,

  // Issues found by the spell checker are marked with a Diagnostic Severity Level. This affects the color of the squiggle.
  //  - Error: Report Spelling Issues as Errors
  //  - Warning: Report Spelling Issues as Warnings
  //  - Information: Report Spelling Issues as Information
  //  - Hint: Report Spelling Issues as Hints, will not show up in Problems
  "cSpell.diagnosticLevel": "Information",

  // Hide the options to add words to dictionaries or settings.
  "cSpell.hideAddToDictionaryCodeActions": false,

  // The maximum number of times the same word can be flagged as an error in a file.
  "cSpell.maxDuplicateProblems": 5,

  // Controls the maximum number of spelling errors per document.
  "cSpell.maxNumberOfProblems": 100,

  // The minimum length of a word before checking it against a dictionary.
  "cSpell.minWordLength": 4,

  // Controls the number of suggestions shown.
  "cSpell.numSuggestions": 8,

  // Show CSpell in-document directives as you type.
  //
  // **Note:** VS Code must be restarted for this setting to take effect.
  "cSpell.showAutocompleteSuggestions": false,

  // Show Spell Checker actions in Editor Context Menu
  "cSpell.showCommandsInEditorContextMenu": true,

  // Display the spell checker status on the status bar.
  "cSpell.showStatus": true,

  // The side of the status bar to display the spell checker status.
  //  - Left: Left Side of Statusbar
  //  - Right: Right Side of Statusbar
  "cSpell.showStatusAlignment": "Right",

  // Show Spelling Suggestions link in the top level context menu.
  "cSpell.showSuggestionsLinkInEditorContextMenu": true,

  // The type of menu used to display spelling suggestions.
  //  - quickPick: Suggestions will appear as a drop down at the top of the IDE. (Best choice for Vim Key Bindings)
  //  - quickFix: Suggestions will appear inline near the word, inside the text editor.
  "cSpell.suggestionMenuType": "quickPick",

  // The maximum number of changes allowed on a word to be considered a suggestions.
  //
  // For example, appending an `s` onto `example` -> `examples` is considered 1 change.
  //
  // Range: between 1 and 5.
  "cSpell.suggestionNumChanges": 3,

  // Verify that the in-document directives are correct.
  "cSpell.validateDirectives": false,

  // Set to false to disable shaking while typing
  "powermode.shake.enabled": true,

  // The intensity with which the screen shakes
  "powermode.shake.intensity": 3,

  // Affects the css properties used to display the gif.
  //  - mask: Uses the gifs as a mask to let the background color come through (similar to atom power mode)
  //  - image: Display the actual gif.
  "powermode.explosions.backgroundMode": "mask",

  // Set custom CSS that will apply to the explosion element.
  "powermode.explosions.customCss": {},

  // This value will go into the 'url()' part of a background image. It should be a base64 encoded gif or **https** URL _without_ quotes.
  "powermode.explosions.customExplosions": [],

  // Determines how long an explosion lasts (in milliseconds). Set to 0 for it to last forever.
  "powermode.explosions.duration": 1000,

  // Set to false to disable explosions while typing
  "powermode.explosions.enabled": true,

  // Determines how the explosions are cycled. 'random' (default) picks from the list randomly. 'sequential' goes through the list in order, and a number will select the explosion at that (zero based)index in the list
  "powermode.explosions.explosionOrder": "random",

  // The number of key strokes needed to trigger an explosion. 2 means every second keystroke will explode, 1 means every key stroke.
  "powermode.explosions.frequency": 2,

  // Control the 'playback' mode of the gifs.
  //  - continue: Resume playing it from its previous point
  //  - restart: Restart the gif each time it is shown. This is useful when you have multiple visible gifs, but may reduce performance
  "powermode.explosions.gifMode": "continue",

  // The maximum number of simultaneous explosions
  "powermode.explosions.maxExplosions": 1,

  // The vertical offset of the explosions. Increasing it will move the explosions up, decreasing it will move them down.
  "powermode.explosions.offset": 0.35,

  // The size of the explosions. For value X, the height is set to X rem and the width to X ch
  "powermode.explosions.size": 6,

  // Control which file schemas will be checked for spelling (VS Code must be restarted for this setting to take effect).
  //
  //
  // Some schemas have special meaning like:
  // - `untitled` - Used for new documents that have not yet been saved
  // - `vscode-notebook-cell` - Used for validating segments of a Notebook.
  // - `vscode-userdata` - Needed to spell check `.code-snippets`
  "cSpell.allowedSchemas": [
    "file",
    "gist",
    "repo",
    "sftp",
    "untitled",
    "vscode-notebook-cell",
    "vscode-scm",
    "vscode-userdata"
  ],

  // By default, the spell checker checks only enabled file types. Use `cSpell.enableFiletypes`
  // to turn on / off various file types.
  //
  // When this setting is `false`, all file types are checked except for the ones disabled by `cSpell.enableFiletypes`.
  // See `cSpell.enableFiletypes` on how to disable a file type.
  "cSpell.checkOnlyEnabledFileTypes": true,

  // Enable / Disable checking file types (languageIds).
  //
  // These are in additional to the file types specified by `cSpell.enabledLanguageIds`.
  // To disable a language, prefix with `!` as in `!json`,
  //
  //
  // **Example: individual file types**
  //
  // ```
  // jsonc       // enable checking for jsonc
  // !json       // disable checking for json
  // kotlin      // enable checking for kotlin
  // ```
  //
  // **Example: enable all file types**
  //
  // ```
  // *           // enable checking for all file types
  // !json       // except for json
  // ```
  "cSpell.enableFiletypes": [],

  // Glob patterns of files to be checked.
  // Glob patterns are relative to the `cSpell.globRoot` of the configuration file that defines them.
  "cSpell.files": [],

  // The root to use for glob patterns found in this configuration.
  // Default: The current workspace folder.
  // Use `globRoot` to define a different location. `globRoot` can be relative to the location of this configuration file.
  // Defining globRoot, does not impact imported configurations.
  //
  // Special Values:
  //
  // - `${workspaceFolder}` - Default - globs will be relative to the current workspace folder\n
  // - `${workspaceFolder:<name>}` - Where `<name>` is the name of the workspace folder.
  "cSpell.globRoot": "",

  // Glob patterns of files to be ignored. The patterns are relative to the `cSpell.globRoot` of the configuration file that defines them.
  "cSpell.ignorePaths": [
    "package-lock.json",
    "node_modules",
    "vscode-extension",
    ".git/objects",
    ".vscode",
    ".vscode-insiders"
  ],

  // Allows this configuration to inherit configuration for one or more other files.
  //
  // See [Importing / Extending Configuration](https://cspell.org/configuration/imports/) for more details.
  "cSpell.import": [],

  // Prevents searching for local configuration when checking individual documents.
  "cSpell.noConfigSearch": false,

  // Only spell check files that are in the currently open workspace.
  // This same effect can be achieved using the `cSpell.files` setting.
  //
  //
  // ```js
  // "cSpell.files": ["/**"]
  // ```
  "cSpell.spellCheckOnlyWorkspaceFiles": false,

  // Tells the spell checker to load `.gitignore` files and skip files that match the globs in the `.gitignore` files found.
  "cSpell.useGitignore": true,

  // Packages managers like Yarn 2 use a `.pnp.cjs` file to assist in loading
  // packages stored in the repository.
  //
  // When true, the spell checker will search up the directory structure for the existence
  // of a PnP file and load it.
  "cSpell.usePnP": false,

  // Define the path to the workspace root folder in a multi-root workspace.
  // By default it is the first folder.
  //
  // This is used to find the `cspell.json` file for the workspace.
  //
  //
  // **Example: use the `client` folder**
  // ```
  // ${workspaceFolder:client}
  // ```
  "cSpell.workspaceRootPath": "",

  // Inline error text render options for dark themes.
  "console-ninja.darkTheme.error.decorationAttachmentRenderOptions": {
    "border": null,
    "borderColor": null,
    "fontStyle": null,
    "fontWeight": null,
    "textDecoration": null,
    "color": "#fe536a",
    "backgroundColor": null,
    "margin": "1em",
    "width": null,
    "height": null
  },

  // Gutter indicators colors for dark themes (requires a restart after change)
  "console-ninja.darkTheme.gutterIcons": {
    "covered": "#62b455",
    "notCovered": "#cccccc",
    "partiallyCovered": "#d2a032",
    "errorSource": "#fe536a"
  },

  // Inline log text render options for dark themes.
  "console-ninja.darkTheme.log.decorationAttachmentRenderOptions": {
    "border": null,
    "borderColor": null,
    "fontStyle": null,
    "fontWeight": null,
    "textDecoration": null,
    "color": "rgba(86, 156, 214, 1)",
    "backgroundColor": null,
    "margin": "1em",
    "width": null,
    "height": null
  },

  // Inline obsolete message text render options for dark themes.
  "console-ninja.darkTheme.obsolete.decorationAttachmentRenderOptions": {
    "border": null,
    "borderColor": null,
    "fontStyle": null,
    "fontWeight": null,
    "textDecoration": null,
    "color": "rgb(153, 153, 153)",
    "backgroundColor": null,
    "margin": "1em",
    "width": null,
    "height": null
  },

  // Inline error text render options for light themes.
  "console-ninja.lightTheme.error.decorationAttachmentRenderOptions": {
    "border": null,
    "borderColor": null,
    "fontStyle": null,
    "fontWeight": null,
    "textDecoration": null,
    "color": "#c80000",
    "backgroundColor": null,
    "margin": "1em",
    "width": null,
    "height": null
  },

  // Gutter indicators colors for light themes (requires a restart after change)
  "console-ninja.lightTheme.gutterIcons": {
    "covered": "#62b455",
    "notCovered": "#cccccc",
    "partiallyCovered": "#d2a032",
    "errorSource": "#fe536a"
  },

  // Inline log text render options for light themes.
  "console-ninja.lightTheme.log.decorationAttachmentRenderOptions": {
    "border": null,
    "borderColor": null,
    "fontStyle": null,
    "fontWeight": null,
    "textDecoration": null,
    "color": "#0000ff",
    "backgroundColor": null,
    "margin": "1em",
    "width": null,
    "height": null
  },

  // Inline obsolete message text render options for light themes.
  "console-ninja.lightTheme.obsolete.decorationAttachmentRenderOptions": {
    "border": null,
    "borderColor": null,
    "fontStyle": null,
    "fontWeight": null,
    "textDecoration": null,
    "color": "rgb(153, 153, 153)",
    "backgroundColor": null,
    "margin": "1em",
    "width": null,
    "height": null
  },

  // The maximum average length of chunks of text without word breaks.
  //
  //
  // A chunk is the characters between absolute word breaks.
  // Absolute word breaks match: `/[\s,{}[\]]/`
  //
  //
  // **Error Message:** _Average Word Size is Too High._
  //
  //
